import numpy as np


def min_max_dist_dim2_16() -> np.ndarray:
    """
    Return 16 points forming a 4-by-4 square lattice.

    The nearest-neighbor distance is 1 and the diameter is sqrt(18).
    """
    return np.array(
        [[float(i), float(j)] for i in range(4) for j in range(4)],
        dtype=float,
    )
